98	## The core fetch (bounded-vs-paginated branch — research.md R1, generation guard — R6)
99	
100	```dart
101	Future<void> _fetchForCriteria(Emitter<RecordsState> emit) async {
102	  final generation = ++_fetchGeneration;
103	  final current = state;
104	  if (current is RecordsLoaded) {
105	    emit(current.copyWith(
106	      isApplyingCriteria: true,
107	      searchQuery: _query, dateRange: _dateRange, entryTypes: _entryTypes,
108	    ));
109	  }
110	  // Nothing to show yet (still on RecordsLoading/RecordsLoadFailure) — RecordsStarted's own
111	  // _loadFirstPage() owns the very first fetch; this path is only reachable once a RecordsLoaded exists.
112	
113	  final now = DateTime.now();
114	  final bounds = _dateRange.boundsAt(now);
115	  final result = await _resolveEntries(
116	    query: _query, dateFrom: bounds.from, dateTo: bounds.to, types: _entryTypes,
117	  );
118	  if (generation != _fetchGeneration) return;   // superseded — discard silently (FR-005a)
119	
120	  result.match(
121	    (failure) {
122	      if (failure is AuthExpiredFailure) _reauthController.add(null);
