141	/// Picks the shape (single call+cursor vs. bounded fan-out-and-merge) per research.md R1.
142	Future<Either<Failure, ({List<Entry> entries, String? nextCursor})>> _resolveEntries({
143	  required String query,
144	  required DateTime? dateFrom,
145	  required DateTime? dateTo,
146	  required Set<EntrySource> types,
147	}) async {
148	  if (types.length <= 1) {
