152	        q: query, source: source, dateFrom: dateFrom, dateTo: dateTo,
153	      );
154	      return result.map((entries) => (entries: entries, nextCursor: null));
155	    }
156	    final result = await _entriesRepository.list(source: source, dateFrom: dateFrom, dateTo: dateTo);
157	    return result.map((page) => (entries: page.entries, nextCursor: page.nextCursor));
158	  }
159	
160	  // 2+ entry types — bounded fan-out, one call per type (research.md R1).
161	  final calls = types.map(
162	    (source) => query.isNotEmpty
163	        ? _entriesRepository.search(q: query, source: source, dateFrom: dateFrom, dateTo: dateTo)
164	        : _entriesRepository.list(source: source, dateFrom: dateFrom, dateTo: dateTo, limit: 50)
165	            .then((r) => r.map((page) => page.entries)),
166	  );
